-- 0124_GeoCityFullUsSeed.sql
-- Full US city/county/ZIP reference seed generated from the public
-- us-state-county-zip dataset. Idempotent set-based inserts; rows already
-- present (including 0123 seed data) are left untouched.

IF OBJECT_ID(N'tempdb..#GeoSeed') IS NOT NULL DROP TABLE #GeoSeed;
CREATE TABLE #GeoSeed (StateCode NVARCHAR(3) NOT NULL, CityName NVARCHAR(120) NOT NULL, County NVARCHAR(120) NULL, PostalCode NVARCHAR(12) NOT NULL);

;
;
;
;
;
;
;
;
;
;
;
;
;
;
;
;
;
;
;
;
;
